<?php require 'config.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$n=trim($_POST['name']??'');$em=strtolower(trim($_POST['email']??''));$pw=$_POST['password']??'';$dept=trim($_POST['department']??'');if(!$n||!filter_var($em,FILTER_VALIDATE_EMAIL)||strlen($pw)<8)$err='Enter valid details; password must be 8+ characters.';else{try{$s=$pdo->prepare('INSERT INTO users(name,department,email,password_hash) VALUES(?,?,?,?)');$s->execute([$n,$dept,$em,password_hash($pw,PASSWORD_DEFAULT)]);msg('Account created. Please log in.');go('login.php');}catch(PDOException $e){$err='Email already registered or database error.';}}} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create Account</title><link rel="stylesheet" href="assets/style.css"></head><body class="auth"><form class="glass authbox" method="post"><div class="brand">◈ NML ICH <small>Complaint Portal</small></div><h1>Create account</h1><?= $err?'<div class="alert">'.e($err).'</div>':''?><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Full name</label><input name="name" required><label>Department</label><input name="department"><label>Email</label><input type="email" name="email" required><label>Password (8+ characters)</label><input type="password" name="password" minlength="8" required><button>Create Account</button><p><a href="login.php">← Back to login</a></p></form></body></html>